const oldExport=downloadCsv;downloadCsv=function(){const rows=[['Lead','Origem','Funil','Etapa','Corretor','Imóvel'],...listLeads().map(l=>[l.name,l.origin,l.funnel,l.stage,l.owner,l.product])],blob=new Blob(['\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(';')).join('\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='CETRO_Leads_do_Recorte.csv';a.click();URL.revokeObjectURL(a.href)};

Object.assign(briefs,{"painel": {"title": "Painel configurável e prioridades operacionais", "points": ["Indicadores selecionáveis: VGV, VGC (comissão), ticket médio, vendas, conversão leads/vendas, leads recebidos, qualificados, visitas e outros.", "Próximos passos: atividades vencidas primeiro, depois prazo das etapas vencido. Bolinha de informação explica o critério.", "Metas de atividade, barras horizontais e ritmo de produção preservados. Metas de conversão ficam em Operação."]}, "funil": {"title": "Funil e ficha completa do lead", "points": ["Filtros visíveis por funil, período, equipe, corretor, origem, temperatura, etiquetas e situação.", "Ao clicar no lead, abra ficha com Lead, Dados, Imóveis, Perfil de busca, Histórico e WhatsApp.", "Inclua anexos, tarefas, visitas, propostas, imóveis vinculados e atribuição completa Meta.", "Mudar proprietário não comprova pré-qualificação SDR; exige mudança SDR → principal.", "Cards mostram telefone, e-mail, tempo na etapa, última interação, próxima atividade, tags e corretor.", "Workflow por etapa: importar documento ou escrever cadência por dia; critérios automáticos de conclusão por envio, ligação ou conversa efetiva.", "Filtros com seleção múltipla. Novo lead inclui e-mail, funil/etapa, corretor ou encaminhamento à catraca."]}, "atender": {"title": "Conversa e contexto no mesmo lugar", "points": ["Tudo, Aguardando, Formulário e Finalizados; filtros por equipe, etapa, temperatura, tags, situação, número e entrada.", "Nome, telefone, responsável e número de saída visíveis. Trazer a conversa para o número da imobiliária.", "Menu de anexos recolhido: fotos, vídeo, documentos, localização e fluxo. Microfone e relógio separados.", "Relógio abre agendamento de texto e mídia/áudio com atalhos e data/hora. Mantê-lo fechado inicialmente.", "Faixa identifica o fluxo em execução, botão Parar e interrupção por resposta do cliente ou mensagem manual.", "Mensagens prontas variam com a etapa; enviar imóvel abre catálogo. Lateral contém IA, tags, formulários, campos personalizados, transferência, simulação, venda e linha do tempo."]}, "catraca": {"title": "Distribuição por origem e por equipe", "points": ["Origens opcionais com seleção independente: WhatsApp da imobiliária/corretor, portais, site e formulários Meta; vazio não significa todos.", "Selecionar um ou vários formulários, números e times. Canal e filtros específicos são configuráveis.", "Funil + etapa acionam distribuição; selecionar ficha de produto, entrada pela atendente ou direto ao corretor, participantes e destino alternativo.", "Prazo para pegar o lead configurável; ao vencer pode passar ao próximo disponível.", "Configurar lead repetido: responsável atual/origem, gestor ou etapa e notificação. Regras específicas prevalecem; desempate explicado."]}, "imoveis": {"title": "Cadastro completo por tipo de imóvel", "points": ["Filtros apenas de imóvel: tipo, planta, quartos, área, bairro/cidade/estado, preço, moeda e estágio.", "Empreendimento e loteamento: Unidades e Comercial juntas, várias unidades/lotes e fluxo próprio em BRL ou USD. Imóvel pronto não tem aba de unidades.", "Área de empreendimento em faixa mínima/máxima. Terreno: frente, fundos e laterais. Loteamento com campos próprios.", "Sinal parcelável, mensais, reforços, chaves e saldo financiado por unidade; dados apresentados na prévia do site.", "Comissão e captador em Geral. Fotos, plantas e vídeo por arquivo ou link. Link de geolocalização aceita Maps/Earth."]}, "cetrolab": {"title": "Site público e identidade do CRM", "points": ["Preserve escolha de modelos, conteúdo, endereço/WhatsApp/Pixel, domínio próprio e SEO.", "A personalização do site público é independente da identidade do CETRO.", "Remova a opção Identidade do CRM cliente. A marca e a identidade visual do CETRO permanecem fixas.", "SEO com nome, título, descrição, contadores e prévia; GTM, código Search Console, URL da propriedade e sitemap com Copiar. Identidade pública independente do CRM."]}, "plantao": {"title": "Plantões separados por times", "points": ["Criar vários plantões e vincular uma ou várias equipes e catracas em cada plantão.", "Selecionar data, turno e participantes. Distribuição depende da catraca e disponibilidade.", "Filtros permitem um, vários ou todos os níveis e corretores."]}, "operacao": {"title": "Funil em cone e campanhas", "points": ["Etapas: Lead, Atendimento qualificado, Agendamento, Visita, Proposta e Venda. Quantidades dentro das faixas do cone.", "Conversão da etapa anterior primeiro; desde a entrada depois. Números maiores e metas por corretor ou operação.", "Vermelho abaixo da meta, verde dentro. Sem base/meta: neutro.", "Carteira atual preservada em rosca, com total central, nomes, quantidades e percentuais.", "Equipe foi unificada ao Score em Relatórios, sem bloco duplicado em Visão geral. Campanhas usa qualificação comercial.", "Corretor fora de Mais filtros, com seleção múltipla. Engrenagem configura metas percentuais de conversão separadas das metas de atividade.", "Taxas organizadas em blocos com fundo. Clicar nas etapas da carteira abre os leads do recorte. VGV presente por origem."]}, "relatorios": {"title": "SDR → Score + Equipe → Individual", "points": ["SDR aparece primeiro se existir na operação. Apenas quem passou pelo funil SDR.", "Pré-qualificação = saída do SDR para o principal. IA atendendo só no principal fica fora da população SDR.", "Responderam, Pré-qualificados e Roleta/corretor mostram quantidade e taxa com denominador explícito.", "Score unifica Equipe e os 19 indicadores. Gestor escolhe pessoas, colunas e pontos positivos/negativos.", "Seleção do corretor em fileira destacada. Resumo individual configurável, cone atualizado e carteira em rosca.", "Corretor visível fora de Mais filtros, com seleção múltipla. Qualquer indicador pode receber peso positivo, negativo ou zero, incluindo tarefas.", "Carteira por etapa abre os leads. Metas percentuais individuais configuráveis pelo gestor."]}, "equipe": {"title": "Hierarquia, ferramentas e indicadores", "points": ["Estrutura começa vazia. Criar apenas os níveis necessários e definir vínculos; nenhuma diretoria ou subgerência obrigatória.", "Um usuário pode acumular Gestor, Corretor e Atendente SDR. Posição hierárquica, funções, permissões e participação em indicadores são independentes.", "Gestor que também produz pode aparecer nos filtros e relatórios. Convite da equipe visível com botão Copiar.", "Permissões respeitam escopo de dados e ferramentas na implementação real."]}, "disparos": {"title": "Disparos e contatos", "points": ["Preserve Novo disparo, texto ou fluxo, anexo, listas/CRM, período e agendamento.", "Contatos: importar lista com origem, data, DDI e autorização; respeitar bloqueios e saída.", "Configuração de ritmo: limite diário, intervalos, horário e número de contingência."]}, "fluxos": {"title": "Fluxos com ações e atividade", "points": ["Gatilhos por formulário, lead, etapa, etiqueta, campo ou mensagem.", "Blocos de mensagem, espera, condição, atividade e mudanças de responsável/funil/etapa.", "Bloco Atividade cria tarefas ou notificações após resposta do cliente.", "Ao mudar de funil, permita selecionar a etapa de destino. Botões de resposta devem aparecer na conversa.", "O editor atual de fluxos deve ser preservado. A apresentação não abre um editor substituto."]}, "redes": {"title": "Programação e relacionamento social", "points": ["Programação, Novo post, Engajamento e Comentários automáticos.", "Post/Reels/Story, foto/vídeo ou imóvel do catálogo, legenda, redes e agendamento.", "Comentários: palavras-chave, posts específicos ou todos, variações públicas e mensagem privada."]}, "formularios": {"title": "Formulário com destino definido", "points": ["Selecione funil e etapa de entrada, catracas e ficha de produto IA por formulário.", "Preserve campanha, conjunto, criativo, formulário e respostas recebidas."]}, "base": {"title": "Base e ações em lote", "points": ["Selecionar um ou vários leads na tabela revela ações em lote; permitir todos os resultados filtrados.", "Transferir responsável, etapa e funil de forma independente; preservar proprietário e/ou etapas ou escolher destino. Validar etapas inexistentes.", "Revisar cada alteração antes de aplicar. Preservar histórico e cancelar envio agendado se o responsável mudar.", "Listas importadas, leads anteriores ao controle e duplicados. Análises de funil, temperatura e reorganização exibem elegíveis, exclusões, custo, progresso e prévia."]}, "config": {"title": "Configurações da operação", "points": ["Prazo da etapa em minutos, horas ou dias; regra específica prevalece sobre o padrão. Opção de configurar individualmente nas etapas.", "Preservar configurações básicas, conversão, início comercial, ações de chegada, etiquetas, primeiro contato e campos obrigatórios. Gestão de tags com contagens.", "Mensagem automática: etapas existentes selecionáveis por funil, mídia e gravação de áudio.", "IA com múltiplas etapas e campos autorizados. Ficha do produto contém apenas produto, descrição e imóvel do catálogo.", "Orientações da IA: editar, desligar/religar, apagar; escrita ou áudio com texto revisado."]}, "conta": {"title": "Minha conta conforme o perfil", "points": ["Gestão: perfil, senha, integrações, agenda, notificações e ferramentas contratadas.", "Corretor: perfil, senha, QR do próprio WhatsApp, IA no primeiro contato, confirmar novos números, grupos e notificações.", "A aparência usa a marca CETRO; a imobiliária personaliza somente seu site público."]}, "disponibilidade": {"title": "Disponibilidade do corretor", "points": ["Ativar/desativar prontidão para o dia e consultar o próprio histórico.", "Disponibilidade define a participação nas catracas autorizadas; não remove leads da carteira."]}, "producao": {"title": "Produção individual do corretor", "points": ["Reutilize o novo formato do relatório individual: indicadores separados, cone com taxas legíveis e carteira em rosca.", "Mostre somente o próprio resultado no perfil básico. Sem seletor de outros corretores ou acesso gerencial."]}, "apresentacao": {"title": "Visão completa do projeto", "points": ["Preserva as etapas 02, 03 e 04 já aprovadas e reúne os módulos adicionais enviados.", "Navegue por cada item do menu e abra os botões internos para visualizar o conteúdo.", "Gestão e Corretor são modos de demonstração. Formulários salvam apenas no navegador."]}});
